def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([2, 4, 10, 3, 5, 4, 2, 5, 2, 4, 7, 3, 2]), fmt([9, 9, 4, 4, 7]), fmt([6, 1, 6, 6]),
             fmt([1, 2, 3, 4]), fmt([-1, -1, 0, 0, 1, 1]), fmt([3, 3, 3]), fmt([1, 2]), fmt([10**9, -10**9, 10**9])]
    for n in (5, 8, 12, 20, 30, 40):
        for k in (2, 4, 8):
            tests.append(fmt([rng.randint(-k, k) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(N)]))
    tests.append(fmt([i // 2 for i in range(N)]))
    return tests
